<template>
 <el-dialog v-model="visible" title="查看报工" class="work-report-dialog" width="min(612px,94vw)" :close-on-click-modal="false" :close-on-press-escape="!reversing" :show-close="!reversing">
  <div class="report-content" v-loading="loading"><p class="process-name">工序名称：{{processName}}</p>
   <el-select v-if="reports.length>1" v-model="reportId" :disabled="loading||reversing" class="batch-select" fit-input-width @change="loadDetail"><el-option v-for="r in reports" :key="r.id" :value="r.id" :label="(r.batchNo||('历史批次'+r.batchId))+' / '+(r.voided?'已作废':stateNames[r.status])"/></el-select>
   <template v-if="report"><el-table :data="report.materials" border class="material-report"><el-table-column label="物料编码" prop="code" width="98"/><el-table-column label="物料名称" prop="name" width="98"/><el-table-column label="损耗重量" prop="lossWeight" width="116"/><el-table-column label="平均损耗" prop="averageLoss"/></el-table>
    <el-collapse class="report-evidence"><el-collapse-item title="查看批次与领还料依据" name="evidence"><p>领料净重：{{report.issuedWeight}}g；还料净重（含产出）：{{report.returnedWeight}}g；完成：{{report.completedQuantity}}件</p><p>损耗：{{report.lossWeight}}g；平均：{{report.averageLoss}}g；阈值：{{report.thresholdValue}}g</p><p>按领用净重比例分摊</p><el-table :data="report.orders" border><el-table-column label="来源单据" prop="orderNo"/><el-table-column label="类型"><template #default="{row}">{{orderTypeNames[row.type]}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{stateNames[row.status]}}</template></el-table-column></el-table><el-button v-if="canReverse&&!report.voided" type="danger" :disabled="loading" :loading="reversing" @click="reverse">批次纠错（冲销）</el-button></el-collapse-item></el-collapse>
   </template>
  </div><template #footer><el-button class="cancel-button" :disabled="reversing" @click="visible=false">取消</el-button><el-button type="primary" :disabled="reversing" @click="visible=false">确认</el-button></template>
 </el-dialog>
</template>
<script setup lang="ts">
import{ref,computed,watch}from'vue';import{ElMessageBox,ElMessage}from'element-plus';import useUserStore from '@/store/modules/user';import{stepReports,warehouseDetail,warehouseAction,stateNames,orderTypeNames,type Row}from'@/api/metal/warehouse';const emit=defineEmits(['changed']),visible=ref(false),reportId=ref(''),processName=ref(''),reports=ref<Row[]>([]),report=ref<Row>(),user=useUserStore(),canReverse=computed(()=>user.permissions.includes('*:*:*')||user.permissions.includes('metal:process-batch:reverse'));
const loading=ref(false),reversing=ref(false)
let detailEpoch=0,openEpoch=0
async function open(itemId:string,processId:string,name:string){if(reversing.value)return;const current=++openEpoch;++detailEpoch;loading.value=true;processName.value=name;report.value=undefined;reports.value=[];reportId.value='';try{const response=await stepReports(itemId,processId);if(current!==openEpoch)return;reports.value=response.data;reportId.value=reports.value.find(r=>!r.voided)?.id||reports.value[0]?.id||'';if(reportId.value)await loadDetail();if(current===openEpoch)visible.value=true}finally{if(current===openEpoch)loading.value=false}}
async function loadDetail(){const current=++detailEpoch,id=reportId.value;loading.value=true;report.value=undefined;try{const response=await warehouseDetail('work-report',id);if(current===detailEpoch&&id===reportId.value)report.value=response.data}finally{if(current===detailEpoch)loading.value=false}}
async function reverse(){if(reversing.value||loading.value||!report.value||report.value.voided||report.value.id!==reportId.value)return;const target={...report.value};reversing.value=true;try{let reason;try{reason=(await ElMessageBox.prompt('填写整体冲销原因','批次纠错',{inputValidator:v=>!!v?.trim()||'请填写原因'})).value}catch{return}await warehouseAction('process-batch',target.batchId,'reverse',{version:target.batchVersion,reason});visible.value=false;ElMessage.success('批次已冲销，原报工保留作废记录');emit('changed')}finally{reversing.value=false}}
watch(visible,value=>{if(!value){++openEpoch;++detailEpoch;report.value=undefined;loading.value=false}})
defineExpose({open})
</script>
<style scoped>
.report-content{padding:0 28px}.process-name{font-weight:600;margin:6px 0 32px}.batch-select{width:100%;margin-bottom:16px}.material-report :deep(th){height:52px;background:#f4f4f4}.material-report :deep(td){height:44px}.material-report :deep(.cell){text-align:center;overflow-wrap:anywhere}.report-evidence{margin-top:16px}.report-evidence :deep(.el-collapse-item__header){font-size:12px;color:#909399}.report-evidence .el-button{margin-top:12px}:deep(.el-dialog__footer){display:flex;justify-content:flex-end;gap:36px;padding:6px 30px 10px}:deep(.el-dialog__footer .el-button){width:88px;height:34px;margin-left:0}:deep(.el-dialog__footer .el-button--primary){background:#577bef;border-color:#577bef}.cancel-button{color:#577bef;border-color:#577bef}
</style>
